export function getTranslation(param1: string, param2: string, defaultText: string = ''): string {
  // Support both getTranslation(lang, key) and getTranslation(key, lang)
  let lang = param1;
  let key = param2;
  
  if ((TRANSLATIONS as any)[param2] && !(TRANSLATIONS as any)[param1]) {
    lang = param2;
    key = param1;
  } else if (param1.includes('.') && !param2.includes('.')) {
    lang = param2;
    key = param1;
  }

  const langDict = (TRANSLATIONS as any)[lang] || (TRANSLATIONS as any)['en'];
  const parts = key.split('.');
  let curr: any = langDict;
  for (const part of parts) {
    if (curr && typeof curr === 'object' && part in curr) {
      curr = curr[part];
    } else {
      curr = undefined;
      break;
    }
  }
  if (typeof curr === 'string' && curr.trim() !== '') {
    return curr;
  }
  // Fallback to English
  const enDict = (TRANSLATIONS as any)['en'];
  let enCurr: any = enDict;
  for (const part of parts) {
    if (enCurr && typeof enCurr === 'object' && part in enCurr) {
      enCurr = enCurr[part];
    } else {
      enCurr = undefined;
      break;
    }
  }
  if (typeof enCurr === 'string' && enCurr.trim() !== '') {
    return enCurr;
  }
  return defaultText || key;
}
